from typing import Optional

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def merge_k_lists(lists: list[Optional[ListNode]]) -> Optional[ListNode]:
    if not lists:
        return None

    dummy = ListNode()
    current = dummy

    while any(node is not None for node in lists):
        min_val = float('inf')
        min_index = -1

        for i, node in enumerate(lists):
            if node is not None and node.val < min_val:
                min_val = node.val
                min_index = i

        if min_index != -1:
            current.next = ListNode(min_val)
            current = current.next
            lists[min_index] = lists[min_index].next

    return dummy.next
```

This solution uses a priority approach to merge the k sorted linked lists. It maintains a dummy node to simplify the merging process and iteratively finds the minimum value among the heads of the lists, appending it to the merged list. The time complexity is O(N log k), where N is the total number of nodes and k is the number of lists. The space complexity is O(1) additional space beyond the output list.
